'use client';

import * as React from 'react';
import { Button } from '@base-ui/react/button';
import './past-banner.css';

/* ─────────────────────────────────────────────────────────
 * PAST BANNER (Kamui 04 §13)
 *   scrubbed  drops in one nest from above on the surface spring (a crossfade under Reduce Motion)
 *   shows     MEMORY · the moment viewed · Back to Now ⎋
 *   back      the cap presses 1; the host returns to the present and unmounts it
 * The only chrome that changes while in the past. It is a live status, so the moment is announced.
 * ───────────────────────────────────────────────────────── */

export interface PastBannerProps {
  /** The moment viewed, as a person reads it: "viewing Tue 23 Sep · 14:10". */
  moment: string;
  onBack: () => void;
  className?: string;
}

/** Says the canvas is showing the past, and brings it back. Shown only while scrubbed. */
export function PastBanner({ moment, onBack, className }: PastBannerProps) {
  return (
    <div role="status" className={['mu-pastbanner', 'mu-frost-graphite', 'type-ui', className].filter(Boolean).join(' ')}>
      <span className="mu-pastbanner-engrave mu-type-label">MEMORY</span>
      <span>{moment}</span>
      <Button className="mu-pastbanner-back type-ui" onClick={onBack} aria-keyshortcuts="Escape">
        Back to Now <span aria-hidden className="mu-pastbanner-key">⎋</span>
      </Button>
    </div>
  );
}

@import "../tokens.css";

/* Past banner (Kamui 04 §13, the medium demo's #pastBanner). */
.mu-pastbanner {
  display: inline-flex;
  align-items: center;
  gap: var(--mu-pastbanner-gap);
  height: var(--mu-pastbanner-height);
  padding: 0 var(--mu-pastbanner-pad-end) 0 var(--mu-pastbanner-pad-start);
  border-radius: 999px;
  color: var(--mu-pastbanner-ink);
  white-space: nowrap;
  /* One nest from above, on the surface spring; a crossfade under Reduce Motion. */
  animation: mu-pastbanner-in var(--mu-spring-surface-d) var(--mu-spring-surface) both;
}
@keyframes mu-pastbanner-in {
  from { opacity: 0; transform: translateY(calc(var(--mu-motion-nest) * -1 * var(--mu-travel-surface))); }
}
.mu-pastbanner-engrave { color: var(--mu-pastbanner-engrave); text-shadow: 0 -1px 0 var(--mu-pastbanner-engrave-lip); }
.mu-pastbanner-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: var(--mu-pastbanner-button-height);
  padding: 0 var(--mu-pastbanner-button-pad);
  border: 0;
  border-radius: 999px;
  color: inherit;
  background: var(--mu-pastbanner-button-bg);
  cursor: pointer;
  transition: background var(--mu-spring-settle-d) var(--mu-spring-settle), transform var(--mu-spring-release-d) var(--mu-spring-release);
}
.mu-pastbanner-back:hover { background: var(--mu-pastbanner-button-hover); }
.mu-pastbanner-back:active { transform: translateY(var(--mu-motion-press)); transition-duration: 50ms; }
.mu-pastbanner-back:focus-visible { outline: var(--mu-focus-width) solid var(--mu-green); outline-offset: var(--mu-focus-offset); }
.mu-pastbanner-key { color: var(--mu-pastbanner-engrave); }
